using System.Reflection;

namespace Rin.World;

/// <summary>
///     The components and tags of one assembly in a fixed order, generated by Rin.SourceGenerators and sorted by full
///     type name.
/// </summary>
public sealed class ComponentModule
{
    private readonly ComponentInfo[] _components;

    public ComponentModule(params ReadOnlySpan<ComponentInfo> components) => _components = components.ToArray();

    /// <summary>
    ///     Every component and tag of Rin.World, reached without reflection.
    /// </summary>
    public static ComponentModule Engine => GeneratedComponents.Module;

    public ReadOnlySpan<ComponentInfo> Components => _components;

    /// <summary>
    ///     The module generated for <paramref name="assembly" />, or null if it declares no components.
    /// </summary>
    /// <remarks>
    ///     Reads the assembly's <see cref="ComponentModuleAttribute" />, so it is for assemblies loaded at run time, like a
    ///     game assembly in the editor. Code that knows the module at compile time uses it directly.
    /// </remarks>
    public static ComponentModule? Of(Assembly assembly) => assembly.GetCustomAttribute<ComponentModuleAttribute>()?.Module;
}
